"use strict";const path=require("path");const tokenizer=require("./shellContextTokenizer");const BLOCKED_PATHS=[{regex:/\/pom\.xml$/,reason:"공유 빌드 파일 (pom.xml) 변경은 모듈 파급 고위험"},{regex:/\/start\.sh$/,reason:"서비스 제어 스크립트 (start.sh) 변경"},{regex:/\/stop\.sh$/,reason:"서비스 제어 스크립트 (stop.sh) 변경"},{regex:/app-kiips\.properties$/i,reason:"프로덕션 설정 파일 변경"},{regex:/app-stg\.properties$/i,reason:"스테이징 설정 파일 변경"},{regex:/app-production\.properties$/i,reason:"프로덕션 설정 파일 변경"}];const BLOCKED_BASH_PATTERNS=[{regex:/(?:^|[\s;&|])(?:\S*\/)?(start|stop)\.sh(?:\s|$|;|&|\|)/,reason:"서비스 제어 스크립트 실행"},{regex:/\bpkill\s+-f\b/,reason:"프로세스 일괄 종료 (pkill -f)"},{regex:/\bkill\s+-9\b/,reason:"프로세스 강제 종료 (kill -9)"},{regex:/\bsystemctl\s+(start|stop|restart)\b/,reason:"systemctl 서비스 제어"},{regex:/\bsvn\s+commit\b/,reason:"SVN commit (영구 기록)"}];const SECRET_FILE_PATTERNS=[{regex:/app-kiips\.properties$/i,reason:"프로덕션 설정 파일 접근"},{regex:/app-stg\.properties$/i,reason:"스테이징 설정 파일 접근"},{regex:/app-production\.properties$/i,reason:"프로덕션 설정 파일 접근"},{regex:/app-tibero\.properties$/i,reason:"Tibero DB 설정 파일 접근"},{regex:/(^|\/)\.env(\.[\w.-]+)?$/i,reason:"환경변수 시크릿(.env) 접근"},{regex:/credentials(\.[\w.-]+)?$/i,reason:"자격증명 파일 접근"},{regex:/\.secret(s)?$/i,reason:"시크릿 파일 접근"}];const SECRET_BASH_PATTERNS=[{regex:/app-kiips\.properties/i,reason:"Bash 를 통한 프로덕션 설정 파일 접근"},{regex:/app-stg\.properties/i,reason:"Bash 를 통한 스테이징 설정 파일 접근"},{regex:/app-production\.properties/i,reason:"Bash 를 통한 프로덕션 설정 파일 접근"},{regex:/app-tibero\.properties/i,reason:"Bash 를 통한 Tibero DB 설정 파일 접근"},{regex:/(?:^|[\s=:/'"])\.env(?:\.[\w.-]+)?\b/i,reason:"Bash 를 통한 .env 시크릿 접근"},{regex:/\bcredentials(?:\.[\w.-]+)?\b/i,reason:"Bash 를 통한 자격증명 파일 접근"}];function checkPermission(toolName,toolInput){const t=(toolName||"").toLowerCase();if(t==="bash"){const cmd=toolInput&&toolInput.command||"";const astFilterEnabled=process.env.KIIPS_PERMISSION_GATE_AST!=="off";for(const entry of BLOCKED_BASH_PATTERNS.concat(SECRET_BASH_PATTERNS)){const globalPattern=entry.regex.global?entry.regex:new RegExp(entry.regex.source,entry.regex.flags+"g");globalPattern.lastIndex=0;let realMatch=null;let m;while((m=globalPattern.exec(cmd))!==null){if(astFilterEnabled){if(!tokenizer.isRealCodeMatch(cmd,m))continue}realMatch=m;break}if(realMatch){return{blocked:true,reason:entry.reason,detail:realMatch[0].trim()}}}return{blocked:false}}if(t==="edit"||t==="write"){const fp=toolInput&&toolInput.file_path||"";if(!fp)return{blocked:false};for(const entry of BLOCKED_PATHS){if(entry.regex.test(fp)){return{blocked:true,reason:entry.reason,detail:path.basename(fp)}}}}if(t==="read"||t==="grep"){const fp=toolInput&&(toolInput.file_path||toolInput.path)||"";if(!fp)return{blocked:false};for(const entry of SECRET_FILE_PATTERNS){if(entry.regex.test(fp)){return{blocked:true,reason:entry.reason,detail:path.basename(fp)}}}}return{blocked:false}}function formatBlockMessage(result){return["━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━","🔒 PERMISSION GATE - User Approval Required","━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━","",`❗ ${result.reason}`,`   대상: ${result.detail}`,"","이 작업은 **사용자 명시 승인** 이 필요합니다.","","진행 방법:","  1. 사용자와 변경 의도·영향 범위를 확인","  2. 필요 시 KIIPS_PERMISSION_GATE=off 환경변수로 게이트 비활성화","  3. 또는 작업을 수동 실행 후 결과 보고","━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━",""].join("\n")}async function onPreToolUse(event){try{if(process.env.KIIPS_PERMISSION_GATE==="off"){return{decision:"allow"}}const result=checkPermission(event.tool_name,event.tool_input||{});if(result.blocked){return{decision:"block",message:formatBlockMessage(result)}}return{decision:"allow"}}catch(e){return{decision:"block",message:`[PermissionGate] Internal error - blocking for safety: ${e.message}`}}}if(require.main===module){const chunks=[];process.stdin.setEncoding("utf8");process.stdin.on("data",c=>chunks.push(c));process.stdin.on("end",async()=>{try{const input=chunks.join("");if(!input.trim()){process.stderr.write("[PermissionGate] Empty input - blocking for safety\n");process.exit(2)}const event=JSON.parse(input);const result=await onPreToolUse(event);if(result.decision==="block"){if(result.message)process.stderr.write(result.message);process.exit(2)}process.exit(0)}catch(e){process.stderr.write(`[PermissionGate] Parse error - blocking for safety: ${e.message}\n`);process.exit(2)}});const timer=setTimeout(()=>{process.stderr.write("[PermissionGate] stdin timeout - blocking for safety\n");process.exit(2)},1e4);process.stdin.on("end",()=>clearTimeout(timer));process.stdin.resume()}module.exports={onPreToolUse:onPreToolUse,checkPermission:checkPermission,formatBlockMessage:formatBlockMessage,BLOCKED_PATHS:BLOCKED_PATHS,BLOCKED_BASH_PATTERNS:BLOCKED_BASH_PATTERNS,SECRET_FILE_PATTERNS:SECRET_FILE_PATTERNS,SECRET_BASH_PATTERNS:SECRET_BASH_PATTERNS};